def choose_move(observation):
    wx, hy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    min_dist = float('inf')
    for r in resources:
        d = dist((px, py), r)
        if d < min_dist:
            min_dist = d
            target = r
    moves = {'up': (0, -1), 'down': (0, 1), 'left': (-1, 0), 'right': (1, 0)}
    for dir_name, (dx, dy) in moves.items():
        nx, ny = px + dx, py + dy
        if 0 <= nx < wx and 0 <= ny < hy and (nx, ny) not in obstacles:
            if target:
                tx, ty = target
                if (dx != 0 and (nx, ny) != (tx, py)) or (dy != 0 and (px, ny) != (px, ty)):
                    continue
            return [dx, dy]
    # try move to eliminate obstacles or stay put
    for dx, dy in moves.values():
        nx, ny = px + dx, py + dy
        if 0 <= nx < wx and 0 <= ny < hy and (nx, ny) not in obstacles:
            return [dx, dy]
    return [0, 0]
